var import_obsidian7 = require("obsidian");
var I18nModIMT = class extends BaseSetting {
  main() {
    const modeToggle = new import_obsidian7.Setting(this.containerEl);
    modeToggle.setName(`${t("\u8BBE\u7F6E_\u6C89\u6D78_\u6807\u9898")}`);
    modeToggle.setDesc(t("\u8BBE\u7F6E_\u6C89\u6D78_\u63CF\u8FF0"));
    modeToggle.addButton((cb) => {
      cb.setButtonText(this.settings.I18N_MODE_IMT ? t("\u8BBE\u7F6E_\u901A\u7528_\u5DF2\u542F\u7528") : t("\u8BBE\u7F6E_\u901A\u7528_\u5DF2\u505C\u7528"));
      cb.onClick(() => {
        this.settings.I18N_MODE_IMT = !this.settings.I18N_MODE_IMT;
        if (!this.settings.I18N_MODE_IMT)
          document.location.reload();
        this.i18n.saveSettings();
        this.settingTab.imtDisplay();
        this.settings.I18N_MODE_IMT ? this.i18n.activateIMT() : this.i18n.activateIMT();
      });
      cb.setClass("i18n-button");
      cb.setClass(`is-${this.settings.I18N_BUTTON_SHAPE}`);
      cb.buttonEl.style.minWidth = "6em";
      this.settings.I18N_MODE_IMT ? cb.setClass(`i18n-button--${this.settings.I18N_BUTTON_TYPE}-success`) : cb.setClass(`i18n-button--${this.settings.I18N_BUTTON_TYPE}-danger`);
    });
    new import_obsidian7.Setting(this.containerEl).setName("\u6838\u5FC3\u7FFB\u8BD1\u8303\u56F4\u63A7\u5236").setDesc("\u7CBE\u786E\u6307\u5B9A\u9700\u8981\u7FFB\u8BD1\u548C\u6392\u9664\u7684\u9875\u9762\u5143\u7D20").setHeading();
    const selectorsTextArea = new import_obsidian7.Setting(this.containerEl);
    selectorsTextArea.setName("\u7FFB\u8BD1\u5339\u914D\u5143\u7D20");
    selectorsTextArea.setDesc(createStructuredDesc({ type: "string[]", desc: "\u7CBE\u786E\u6307\u5B9A\u9700\u8981\u7FFB\u8BD1\u7684\u9875\u9762\u5143\u7D20", example: "", notice: "\u4E00\u884C\u4EE3\u8868\u4E00\u4E2A\u9009\u62E9\u5668" }));
    selectorsTextArea.addTextArea(
      (cb) => cb.setValue(this.settings.I18N_IMT_PAGERULE.selectors ? this.settings.I18N_IMT_PAGERULE.selectors.join("\n") : "").onChange(async (v) => {
        this.settings.I18N_IMT_PAGERULE.selectors = v.split("\n").filter((item) => typeof item === "string" && item.trim() !== "");
        console.log("\u66F4\u65B0\u7FFB\u8BD1\u5339\u914D\u5143\u7D20:", this.settings.I18N_IMT_PAGERULE.selectors);
        await this.i18n.saveSettings();
      }).inputEl.onblur = () => {
        new import_obsidian7.Notice("\u8BF7\u91CD\u542F\u4EE5\u5E94\u7528\u65B0\u7684\u7FFB\u8BD1\u5339\u914D\u5143\u7D20\u8BBE\u7F6E", 5e3);
      }
    );
    const excludeSelectorsTextArea = new import_obsidian7.Setting(this.containerEl);
    excludeSelectorsTextArea.setName("\u6392\u9664\u5339\u914D\u7FFB\u8BD1");
    excludeSelectorsTextArea.setDesc(createStructuredDesc({ type: "string[]", desc: "\u660E\u786E\u6307\u5B9A\u4E0D\u9700\u8981\u7FFB\u8BD1\u7684\u9875\u9762\u5143\u7D20", example: "", notice: "" }));
    excludeSelectorsTextArea.addTextArea(
      (cb) => cb.setValue(this.settings.I18N_IMT_PAGERULE.excludeSelectors ? this.settings.I18N_IMT_PAGERULE.excludeSelectors.join("\n") : "").onChange(async (v) => {
        this.settings.I18N_IMT_PAGERULE.excludeSelectors = v.split("\n").filter((item) => typeof item === "string" && item.trim() !== "");
        ;
        await this.i18n.saveSettings();
      }).inputEl.onblur = () => {
        new import_obsidian7.Notice("\u8BF7\u91CD\u542F\u4EE5\u5E94\u7528\u65B0\u7684\u7FFB\u8BD1\u5339\u914D\u5143\u7D20\u8BBE\u7F6E", 5e3);
      }
    );
  }
};
var createStructuredDesc = (config) => {
  const fragment = new DocumentFragment();
  fragment.createDiv({}, (div) => {
    div.innerHTML = `
              
              <div>
                  <span>\u63CF\u8FF0\uFF1A</span>
                  ${config.desc}
              </div>
              ${config.notice ? `<div>${config.notice}</div>` : ""}
          `;
  });
  return fragment;
};

